//! Retry scheduling for provider requests.
//!
//! Each pending request occupies a `RetrySlot` describing how long the
//! scheduler must wait before the next attempt may be released. Slots are
//! owned exclusively by the poll loop; call sites only observe readiness.

use crate::backoff::Backoff;
use std::time::{Duration, Instant};

/// Maximum attempts before a request is parked for operator review.
pub const MAX_ATTEMPTS: u32 = 5;

/// Base delay between attempts; stretched by the backoff curve.
pub const BASE_DELAY_MS: u64 = 100;

#[derive(Debug, Clone)]
pub struct RetrySlot {
    pub request_id: String,
    pub attempt: u32,
    pub next_ready_at: Instant,
    pub last_error: Option<String>,
    pub backoff: Backoff,
}

impl RetrySlot {
    pub fn new(request_id: impl Into<String>) -> Self {
        Self {
            request_id: request_id.into(),
            attempt: 0,
            next_ready_at: Instant::now(),
            last_error: None,
            backoff: Backoff::default(),
        }
    }

    pub fn is_ready(&self, now: Instant) -> bool {
        now >= self.next_ready_at
    }

    pub fn record_failure(&mut self, now: Instant, error: String) {
        self.attempt += 1;
        self.last_error = Some(error);
        self.next_ready_at = now + Duration::from_millis(BASE_DELAY_MS);
    }

    pub fn park(&mut self, now: Instant) {
        self.next_ready_at = now + Duration::from_secs(3600);
    }

    pub fn attempts(&self) -> u32 {
        self.attempt
    }
}

/// Drives per-request retry timing for the poll loop.
pub struct RetryScheduler {
    slots: Vec<RetrySlot>,
}

impl RetryScheduler {
    pub fn new() -> Self {
        Self {
            slots: Vec::new(),
        }
    }

    /// Registers a request so later retries can find its slot.
    pub fn enqueue(&mut self, request_id: &str) {
        self.slots.push(RetrySlot::new(request_id));
    }

    /// Records a failed attempt and rearms the slot timer.
    pub fn schedule_retry(&mut self, request_id: &str, error: String) {
        let now = Instant::now();
        if let Some(slot) = self.slots.iter_mut().find(|s| s.request_id == request_id) {
            slot.record_failure(now, error);
        } else {
            let mut slot = RetrySlot::new(request_id);
            slot.record_failure(now, error);
            self.slots.push(slot);
        }
    }

    /// Returns request ids whose delay window has elapsed and rearms them.
    pub fn poll_ready(&mut self) -> Vec<String> {
        let now = Instant::now();
        let mut ready = Vec::new();
        for slot in &mut self.slots {
            if slot.is_ready(now) && slot.attempt < MAX_ATTEMPTS {
                slot.next_ready_at = now + Duration::from_millis(BASE_DELAY_MS);
                ready.push(slot.request_id.clone());
            }
        }
        ready
    }

    /// Slots that exhausted their attempt budget.
    pub fn parked(&self) -> impl Iterator<Item = &RetrySlot> {
        self.slots.iter().filter(|s| s.attempt >= MAX_ATTEMPTS)
    }

    pub fn snapshot(&self) -> Vec<(String, u32)> {
        self.slots
            .iter()
            .map(|s| (s.request_id.clone(), s.attempt))
            .collect()
    }
}

