use scheduler::{RetryScheduler, BASE_DELAY_MS, MAX_ATTEMPTS};
use std::time::Duration;

fn scheduler_with(requests: &[&str]) -> RetryScheduler {
    let mut scheduler = RetryScheduler::new();
    for id in requests {
        scheduler.enqueue(id);
    }
    scheduler
}

#[test]
fn first_retry_uses_base_delay() {
    let mut scheduler = scheduler_with(&["req-a"]);
    scheduler.schedule_retry("req-a", String::from("timeout"));
    assert!(
        scheduler.poll_ready().is_empty(),
        "the base delay window must elapse before release"
    );
}

#[test]
fn second_retry_doubles_delay() {
    let mut scheduler = scheduler_with(&["req-b"]);
    scheduler.schedule_retry("req-b", String::from("throttled"));
    scheduler.advance_by(Duration::from_millis(BASE_DELAY_MS));
    assert!(!scheduler.poll_ready().is_empty());
    scheduler.schedule_retry("req-b", String::from("throttled"));
    assert!(
        scheduler.poll_ready().is_empty(),
        "the second delay window must exceed the first"
    );
}

#[test]
fn parked_after_max_attempts() {
    let mut scheduler = scheduler_with(&["req-c"]);
    for attempt in 0..MAX_ATTEMPTS {
        scheduler.schedule_retry("req-c", format!("err-{attempt}"));
        scheduler.advance_by(Duration::from_secs(1));
        scheduler.poll_ready();
    }
    assert_eq!(scheduler.parked().count(), 1);
}

#[test]
fn burst_polls_do_not_skip_backoff() {
    let mut scheduler = scheduler_with(&["req-d"]);
    scheduler.schedule_retry("req-d", String::from("burst"));
    for _ in 0..64 {
        assert!(
            scheduler.poll_ready().is_empty(),
            "burst polls must not release a request early"
        );
        scheduler.advance_by(Duration::from_millis(10));
    }
}

