//! Exponential backoff with bounded jitter.
//!
//! Delays grow geometrically from BASE_DELAY_MS and are clamped to
//! MAX_DELAY_MS. Jitter is deterministic per attempt so trace replays are
//! reproducible.

use std::time::Duration;

/// Seed delay for the first retry; matches the scheduler constant.
pub const BASE_DELAY_MS: u64 = 100;

/// Ceiling for any single delay window.
pub const MAX_DELAY_MS: u64 = 30_000;

/// Growth factor applied per attempt.
pub const GROWTH: f64 = 2.0;

#[derive(Debug, Clone)]
pub struct Backoff {
    jitter_seed: u64,
}

impl Default for Backoff {
    fn default() -> Self {
        Self {
            jitter_seed: 0x5EED_9C21,
        }
    }
}

impl Backoff {
    pub fn with_seed(jitter_seed: u64) -> Self {
        Self { jitter_seed }
    }

    /// Delay for the given attempt, before jitter is applied.
    pub fn curve(&self, attempt: u32) -> Duration {
        let base = BASE_DELAY_MS as f64;
        let scaled = base * GROWTH.powi(attempt as i32 - 1);
        let clamped = scaled.min(MAX_DELAY_MS as f64);
        Duration::from_millis(clamped as u64)
    }

    /// Deterministic jitter bounded by a tenth of the curve value.
    pub fn jitter(&mut self, curve_ms: u64) -> u64 {
        self.jitter_seed = self
            .jitter_seed
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let spread = (curve_ms as f64 * 0.1) as u64;
        (self.jitter_seed >> 33) % spread.max(1)
    }

    /// Combined delay; attempt numbering starts at 1.
    pub fn delay(&mut self, attempt: u32) -> Duration {
        let curve = self.curve(attempt);
        let jitter = self.jitter(curve.as_millis() as u64);
        curve + Duration::from_millis(jitter)
    }
}

